      </div><button class="btn outline" type="submit">Update cart</button>
    </form>
    <?php endif; ?>
  </div>
  <aside class="order-summary"><p class="kicker">Summary</p><div><span>Items</span><b data-cart-count><?= cart_count() ?></b></div><div><span>Subtotal</span><b data-cart-subtotal><?= money(cart_total()) ?></b></div><?php if($siCart['enabled']):?><div class="si-cart-progress" data-cart-progress><div><span><?= $siCart['gap']>0 ? e(money($siCart['gap']).' away from checkout') : 'Minimum order reached' ?></span><b><?=e((string)$siCart['progress'])?>%</b></div><i><span style="width:<?=e((string)$siCart['progress'])?>%"></span></i><small>Minimum order <?=money($siCart['minimum'])?></small></div><?php endif;?><div><span>Shipping</span><b>Calculated by pincode</b></div><div class="summary-total"><span>Cart subtotal</span><strong data-cart-total><?= money(cart_total()) ?></strong></div><?php if($lines):?><?php if(!$siCart['enabled']||$siCart['gap']===0):?><a class="btn primary wide" href="<?=e(url(customer_logged_in()?'/checkout':'/account/login'))?>" data-intel-event="checkout_started"><?=customer_logged_in()?'Proceed to checkout':'Sign in to checkout'?></a><?php else:?><button class="btn primary wide" type="button" disabled>Add <?=money($siCart['gap'])?> more to checkout</button><?php endif;?><?php endif;?><small>No real payment is collected in staging. Sandbox payment only.</small></aside>
</section>

